"""Auto-generated gRPC stubs. Regenerate with scripts/regen_protos.sh.

grpcio-tools emits modules that import each other via absolute paths
(e.g. `from dcs.common.v0 import common_pb2`). To make those resolve without
mangling the generated files, we add this directory to sys.path on import.
"""

import sys
from pathlib import Path

_HERE = Path(__file__).parent
if str(_HERE) not in sys.path:
    sys.path.insert(0, str(_HERE))
